INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('cc8eebc5-470d-53ba-ba99-9ece89c3a6d2', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 7, 7, 'Hydrogen gas in a discharge tube glows red, with a strong line at 656 nm. Calculate the photon energy of this line in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.895', 'eV', false, NULL, false, NULL, 'E = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (656 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 1.90 eV. Mark scheme (2 marks). C1: E = hc/λ in eV. A1: E = 1.90 eV.', 2, NULL, NULL),
('1a533ed7-3a4a-51b5-99e3-afb6353fd1cf', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 8, 8, 'Why does a low-pressure gas in a discharge tube emit light?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons collide with atoms and excite them; the atoms then emit photons as they de-excite', NULL, false, NULL, false, NULL, 'Collisions raise electrons to higher levels; each fall emits a photon of the level difference. Mark scheme (1 mark). B1: C (Electrons collide with atoms and excite them; the atoms then emit photons as they de-excite).', 1, NULL, NULL),
('3c887b60-e627-58d8-b878-170416e81176', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 9, 9, 'A diffraction grating with slit spacing 2.0 × 10⁻⁶ m is used to view the 589 nm line of sodium. Calculate the first-order angle of the line in degrees.', NULL, 1, 'numeric'::answer_type, '17.13', '°', false, NULL, false, NULL, 'sin θ = λ/d = 589 × 10⁻⁹ ÷ 2.0 × 10⁻⁶ = 0.2945, so θ = sin⁻¹ 0.2945 = 17.1°. Mark scheme (2 marks). C1: d sin θ = nλ. A1: θ = 17.1°.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 280" role="img" aria-labelledby="fg3251d316-t fg3251d316-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3251d316-t">Viewing a line with a grating</title><desc id="fg3251d316-d">Light of wavelength 589 nm falls normally on a grating of slit spacing 2.0 × 10⁻⁶ m; the first-order beams leave at an angle θ on each side of the straight-through beam.</desc><line x1="20" y1="140" x2="140" y2="140" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,140 102.7,143.4 102.7,136.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="140" y1="30" x2="140" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="36" x2="144" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="44" x2="144" y2="44" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="52" x2="144" y2="52" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="60" x2="144" y2="60" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="68" x2="144" y2="68" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="76" x2="144" y2="76" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="84" x2="144" y2="84" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="92" x2="144" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="100" x2="144" y2="100" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="108" x2="144" y2="108" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="116" x2="144" y2="116" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="124" x2="144" y2="124" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="132" x2="144" y2="132" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="140" x2="144" y2="140" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="148" x2="144" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="156" x2="144" y2="156" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="164" x2="144" y2="164" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="172" x2="144" y2="172" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="180" x2="144" y2="180" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="188" x2="144" y2="188" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="196" x2="144" y2="196" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="204" x2="144" y2="204" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="212" x2="144" y2="212" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="220" x2="144" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="228" x2="144" y2="228" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="236" x2="144" y2="236" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="244" x2="144" y2="244" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="140" y1="140" x2="358" y2="140" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="362" y="140" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">n = 0</text><line x1="140" y1="140" x2="343" y2="77.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="348.3,75.8 342.4,81.2 340.4,74.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="352.3" y="71.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="140" y1="140" x2="343" y2="202.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="348.3,204.2 340.4,205.3 342.4,198.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M210,140 A70,70 0 0,0 206.9,119.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="225" y="127.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">θ</text><text x="140" y="18" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">grating</text><text x="140" y="266" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">d = 2.0 × 10⁻⁶ m</text></svg>', 'Light of wavelength 589 nm falls normally on a grating of slit spacing 2.0 × 10⁻⁶ m; the first-order beams leave at an angle θ on each side of the straight-through beam.'),
('76d21d02-d4b9-546a-946f-654d666b64a4', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 10, 10, 'What does the emission spectrum of a hot, low-pressure gas look like?', NULL, 1, 'multiple_choice'::answer_type, 'Bright coloured lines on a dark background', NULL, false, NULL, false, NULL, 'Only photons of certain energies are emitted. Mark scheme (1 mark). B1: A (Bright coloured lines on a dark background).', 1, NULL, NULL),
('7d130aa6-ed4c-5154-b1c5-a3e8b389bfd5', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 11, 11, 'A spectral line has a photon energy of 2.11 eV. Calculate its wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '589.2 nm', 'nm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.11 × 1.60 × 10⁻¹⁹) = 5.892 × 10⁻⁷ m. In nm: 5.892 × 10⁻⁷ × 10⁹ = 589. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 589 nm.', 2, NULL, NULL),
('27610d28-d303-5150-875d-b1ac581b9a25', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 12, 12, 'What does an absorption spectrum look like?', NULL, 1, 'multiple_choice'::answer_type, 'A continuous spectrum crossed by dark lines', NULL, false, NULL, false, NULL, 'Atoms remove the photons that match their level gaps. Mark scheme (1 mark). B1: D (A continuous spectrum crossed by dark lines).', 1, NULL, NULL),
('ce35adc2-c3c3-5a9e-8dbf-f829d7e2242d', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 13, 13, 'A violet line in the hydrogen spectrum has a wavelength of 434 nm. Calculate the energy difference between the levels involved, in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '4.583', '10⁻¹⁹ J', false, NULL, false, NULL, 'ΔE = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 434 × 10⁻⁹ = 4.58 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: ΔE = hc/λ. A1: ΔE = 4.58 × 10⁻¹⁹ J.', 2, NULL, NULL),
('fde9337f-651f-5b5c-a6fd-2beb037b1559', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 14, 14, 'What kind of spectrum does the glowing filament of an incandescent lamp produce?', NULL, 1, 'multiple_choice'::answer_type, 'A continuous spectrum', NULL, false, NULL, false, NULL, 'A hot dense solid emits all wavelengths. Mark scheme (1 mark). B1: B (A continuous spectrum).', 1, NULL, NULL),
('2a444311-8778-50d6-8af3-b21d1bbc1045', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 15, 15, 'A grating has slits 2.0 × 10⁻⁶ m apart. A line appears in the second order at 30.0°. Calculate its wavelength in nm.', NULL, 1, 'numeric'::answer_type, '500 nm', 'nm', false, NULL, false, NULL, 'λ = d sin θ / n = 2.0 × 10⁻⁶ × sin 30.0° ÷ 2 = 5.000 × 10⁻⁷ m. In nm: 5.000 × 10⁻⁷ × 10⁹ = 500. Mark scheme (2 marks). C1: nλ = d sin θ. A1: λ = 500 nm.', 2, NULL, NULL),
('b19a273f-1fa6-5428-9175-c561498cd26e', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 16, 16, 'The dark Fraunhofer lines in sunlight are evidence of what?', NULL, 1, 'multiple_choice'::answer_type, 'Elements in the cooler outer layers of the Sun absorbing particular wavelengths', NULL, false, NULL, false, NULL, 'Each set of lines matches the levels of a particular element. Mark scheme (1 mark). B1: C (Elements in the cooler outer layers of the Sun absorbing particular wavelengths).', 1, NULL, NULL),
('6eca8043-0dae-5111-bc14-c7b3017e5b80', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 17, 17, 'An atom has five energy levels. How many different spectral lines can it emit?', NULL, 1, 'numeric'::answer_type, '10', NULL, false, NULL, false, NULL, 'Number of pairs = 4 + 3 + 2 + 1 = 10. Mark scheme (2 marks). C1: count each pair once. A1: lines = 10.', 2, NULL, NULL),
('c50673a7-a78e-5d2d-9d17-3f0493059525', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 18, 18, 'Why do absorption lines look dark even though the absorbing atoms re-emit photons?', NULL, 1, 'multiple_choice'::answer_type, 'The photons are re-emitted in all directions, so few continue towards the observer', NULL, false, NULL, false, NULL, 'The beam loses those wavelengths in the forward direction. Mark scheme (1 mark). B1: A (The photons are re-emitted in all directions, so few continue towards the observer).', 1, NULL, NULL),
('89685854-f259-5588-b1d4-1bdb68192f23', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 19, 19, 'Calculate the frequency of the 656 nm hydrogen line in units of 10¹⁴ Hz. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '4.573', '10¹⁴ Hz', false, NULL, false, NULL, 'f = c/λ = 3.00 × 10⁸ ÷ 656 × 10⁻⁹ = 4.57 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f = c/λ. A1: f = 4.57 × 10¹⁴ Hz.', 2, NULL, NULL),
('2f4f9250-bb9b-5684-953a-b35a28d28227', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 20, 20, 'How can a gas be made to show its emission line spectrum?', NULL, 1, 'multiple_choice'::answer_type, 'By passing an electric discharge through it at low pressure', NULL, false, NULL, false, NULL, 'The discharge excites the atoms, which then emit their characteristic lines. Mark scheme (1 mark). B1: D (By passing an electric discharge through it at low pressure).', 1, NULL, NULL),
('407d95b9-06d0-5ec4-a719-b3a0f3c01dc1', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 21, 21, 'Electrons in a discharge tube are accelerated through 15 V. Calculate the kinetic energy of each electron in units of 10⁻¹⁸ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '2.4', '10⁻¹⁸ J', false, NULL, false, NULL, 'Ek = eV = 1.60 × 10⁻¹⁹ × 15 = 2.4 × 10⁻¹⁸ J. Mark scheme (2 marks). C1: Ek = eV. A1: Ek = 2.4 × 10⁻¹⁸ J.', 2, NULL, NULL),
('72eb297b-3625-54a6-8173-745c69a8eaa3', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 22, 22, 'Helium was first discovered from the Sun''s spectrum. What made this possible?', NULL, 1, 'multiple_choice'::answer_type, 'A set of lines matched no element then known on Earth', NULL, false, NULL, false, NULL, 'Each element has its own pattern of lines. Mark scheme (1 mark). B1: B (A set of lines matched no element then known on Earth).', 1, NULL, NULL),
('9debe970-0ed8-597d-b0dc-1e1826024404', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 23, 23, 'An electron falls through an energy gap of 1.9 eV. Express this gap in units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.04', '10⁻¹⁹ J', false, NULL, false, NULL, 'ΔE = 1.9 × 1.60 × 10⁻¹⁹ = 3.04 × 10⁻¹⁹ J. Mark scheme (1 mark). A1: ΔE = 3.04 × 10⁻¹⁹ J.', 1, NULL, NULL),
('5ae873dd-dda9-5cb4-bd82-9059374a76a0', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 24, 24, 'A spectral line has a frequency of 6.17 × 10¹⁴ Hz. Calculate its wavelength in nm. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '486.2 nm', 'nm', false, NULL, false, NULL, 'λ = c/f = 3.00 × 10⁸ ÷ 6.17 × 10¹⁴ = 4.862 × 10⁻⁷ m. In nm: 4.862 × 10⁻⁷ × 10⁹ = 486. Mark scheme (2 marks). C1: λ = c/f. A1: λ = 486 nm.', 2, NULL, NULL),
('e82aee1f-c748-5de0-a1da-36784b160d7d', '7d22edfc-44c4-4846-9769-292936cb7827', '8e9dd5f1-dd78-4ce4-8525-76c12991e03f', 'a-level', '28.7', '9702 coursebook 28.7 · Explaining the origin of line spectra', 25, 25, 'A grating with 600 lines per mm is used to view the red 656 nm line of hydrogen. Calculate the first-order angle in degrees.', NULL, 2, 'numeric'::answer_type, '23.18', '°', false, NULL, false, NULL, 'd = 1 ÷ 600 × 10³ = 1.667 × 10⁻⁶ m. sin θ = 656 × 10⁻⁹ ÷ 1.667 × 10⁻⁶ = 0.3936, so θ = sin⁻¹ 0.3936 = 23.2°. Mark scheme (3 marks). C1: d from lines per mm. C1: d sin θ = λ. A1: θ = 23.2°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 280" role="img" aria-labelledby="fgb05bd1f5-t fgb05bd1f5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb05bd1f5-t">Hydrogen red line</title><desc id="fgb05bd1f5-d">Light of wavelength 656 nm falls normally on a grating with 600 lines per mm; first-order beams leave at angle θ.</desc><line x1="20" y1="140" x2="140" y2="140" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,140 102.7,143.4 102.7,136.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="140" y1="30" x2="140" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="36" x2="144" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="44" x2="144" y2="44" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="52" x2="144" y2="52" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="60" x2="144" y2="60" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="68" x2="144" y2="68" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="76" x2="144" y2="76" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="84" x2="144" y2="84" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="92" x2="144" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="100" x2="144" y2="100" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="108" x2="144" y2="108" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="116" x2="144" y2="116" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="124" x2="144" y2="124" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="132" x2="144" y2="132" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="140" x2="144" y2="140" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="148" x2="144" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="156" x2="144" y2="156" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="164" x2="144" y2="164" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="172" x2="144" y2="172" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="180" x2=