('04f599c3-843c-504c-8ca9-7cd5dd566cd7', 'd326191e-2f32-597a-830a-203cc1c645c1', 'They depend on the distance of the source', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('593965b5-c0b0-5536-9a1d-b50522c4f9f6', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 7, 7, 'A violet photon has a frequency of 9.0 × 10¹⁴ Hz. How much energy does it carry? Answer in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '5.967', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 9.0 × 10¹⁴ = 5.97 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: E = hf. A1: E = 5.97 × 10⁻¹⁹ J.', 2, NULL, NULL),
('e2a4c2d4-08f5-565a-bbda-5742a63cf96d', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 8, 8, 'How many joules are there in one electronvolt?', NULL, 1, 'multiple_choice'::answer_type, '1.60 × 10⁻¹⁹ J', NULL, false, NULL, false, NULL, '1 eV = e × 1 V = 1.60 × 10⁻¹⁹ J. Mark scheme (1 mark). B1: C (1.60 × 10⁻¹⁹ J).', 1, NULL, NULL),
('c1c3d464-a5df-5372-bf58-3bda25ec0a86', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 9, 9, 'Convert a photon energy of 4.0 eV into units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '6.4', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = 4.0 × 1.60 × 10⁻¹⁹ = 6.4 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: × 1.60 × 10⁻¹⁹. A1: E = 6.4 × 10⁻¹⁹ J.', 2, NULL, NULL),
('69dd64ab-7d58-533b-b0e2-eb257912cad6', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 10, 10, 'Photon A has three times the frequency of photon B. What is (energy of A) ÷ (energy of B)?', NULL, 1, 'multiple_choice'::answer_type, '3', NULL, false, NULL, false, NULL, 'E = hf, so E is proportional to f. Mark scheme (1 mark). B1: A (3).', 1, NULL, NULL),
('8b61eb61-3fe9-58f1-982f-32e734b9969a', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 11, 11, 'An infrared photon carries 2.4 × 10⁻¹⁹ J. What is this energy in eV? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.5', 'eV', false, NULL, false, NULL, 'E = 2.4 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 1.5 eV. Mark scheme (2 marks). C1: ÷ 1.60 × 10⁻¹⁹. A1: E = 1.5 eV.', 2, NULL, NULL),
('6155dcf2-6cf4-5b6a-9377-45d188de5b50', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 12, 12, 'A photon has an energy of about 2 eV. In which region of the electromagnetic spectrum is it?', NULL, 1, 'multiple_choice'::answer_type, 'Visible light', NULL, false, NULL, false, NULL, 'Visible photons have energies from about 1.7 eV to 3.3 eV. Mark scheme (1 mark). B1: D (Visible light).', 1, NULL, NULL),
('dbbe60a8-22a7-5d75-8e8a-509054296746', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 13, 13, 'Calculate the energy of an X-ray photon of wavelength 0.020 nm, in keV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '62.16', 'keV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 0.020 × 10⁻⁹ = 9.945 × 10⁻¹⁵ J. In keV: 9.945 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁶ = 62.2. Mark scheme (2 marks). C1: E = hc/λ then ÷ 1.60 × 10⁻¹⁶. A1: E = 62.2 keV.', 2, NULL, NULL),
('432fcb4f-3c60-5b22-a439-b040bf487330', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 14, 14, 'In the photon energy equation E = hf, what does the symbol h stand for?', NULL, 1, 'multiple_choice'::answer_type, 'The Planck constant', NULL, false, NULL, false, NULL, 'h = 6.63 × 10⁻³⁴ J s links photon energy to frequency. Mark scheme (1 mark). B1: B (The Planck constant).', 1, NULL, NULL),
('12bc5d2e-ddc8-5f7b-acf9-940d1b18c301', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 15, 15, 'Calculate the energy, in eV, of an infrared photon of wavelength 1500 nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.8287', 'eV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1500 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 0.829 eV. Mark scheme (2 marks). C1: E = hc/λ in eV. A1: E = 0.829 eV.', 2, NULL, NULL),
('2244f597-40e0-5608-a59e-481215e0c35c', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 16, 16, 'The electronvolt is a unit of which quantity?', NULL, 1, 'multiple_choice'::answer_type, 'Energy', NULL, false, NULL, false, NULL, 'It is the energy gained by an electron moving through 1 V. Mark scheme (1 mark). B1: C (Energy).', 1, NULL, NULL),
('af453007-ff48-5663-aaf6-1c061bc8258f', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 17, 17, 'Calculate the wavelength, in nm, of a photon of energy 1.0 eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1243 nm', 'nm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.0 × 1.60 × 10⁻¹⁹) = 1.243 × 10⁻⁶ m. In nm: 1.243 × 10⁻⁶ × 10⁹ = 1240. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 1240 nm.', 2, NULL, NULL),
('f8306633-a242-5094-9a94-492fa5c0ecbb', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 18, 18, 'Which photon energy could NOT belong to visible light?', NULL, 1, 'multiple_choice'::answer_type, '5.0 eV', NULL, false, NULL, false, NULL, '5.0 eV is about 250 nm, in the ultraviolet. Mark scheme (1 mark). B1: A (5.0 eV).', 1, NULL, NULL),
('2855e04d-4ec7-59bb-a308-85d86348eed7', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 19, 19, 'Calculate the energy, in keV, of a photon of frequency 1.0 × 10²⁰ Hz. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '414.4', 'keV', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 1.0 × 10²⁰ = 6.63 × 10⁻¹⁴ J. In keV: 6.63 × 10⁻¹⁴ ÷ 1.60 × 10⁻¹⁶ = 414. Mark scheme (2 marks). C1: E = hf then convert. A1: E = 414 keV.', 2, NULL, NULL),
('f6996866-2de0-5ace-8c47-9425ee089753', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 20, 20, 'Which list is in order of increasing photon energy?', NULL, 1, 'multiple_choice'::answer_type, 'Radio, microwave, infrared, visible', NULL, false, NULL, false, NULL, 'Photon energy rises with frequency. Mark scheme (1 mark). B1: D (Radio, microwave, infrared, visible).', 1, NULL, NULL),
('b2cd8c37-98fa-5783-ba1f-f850ef2785ce', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 21, 21, 'A photon has an energy of 3.1 eV. Calculate its frequency in units of 10¹⁴ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '7.481', '10¹⁴ Hz', false, NULL, false, NULL, 'f = E/h = 3.1 × 1.60 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 7.48 × 10¹⁴ Hz. Mark scheme (2 marks). C1: eV to J then f = E/h. A1: f = 7.48 × 10¹⁴ Hz.', 2, NULL, NULL),
('b02bb9b7-6460-5afa-acfa-79481528c2e2', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 22, 22, 'Thermal radiation from a warm object has photons of about 6.0 × 10⁻²⁰ J each. Convert this photon energy to eV. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.375', 'eV', false, NULL, false, NULL, 'E = 6.0 × 10⁻²⁰ ÷ 1.60 × 10⁻¹⁹ = 0.375 eV. Mark scheme (1 mark). A1: E = 0.375 eV.', 1, NULL, NULL),
('833c347b-5b24-5c32-8e46-c2bc614dfaaa', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 23, 23, 'A photon of green light has a wavelength of 530 nm. Calculate its frequency in units of 10¹⁴ Hz. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '5.66', '10¹⁴ Hz', false, NULL, false, NULL, 'f = c/λ = 3.00 × 10⁸ ÷ 530 × 10⁻⁹ = 5.66 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f = c/λ. A1: f = 5.66 × 10¹⁴ Hz.', 2, NULL, NULL),
('7a6f2889-ff08-5b57-8d0c-27f51e693a9a', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 24, 24, 'A red LED emits light of wavelength 620 nm and just starts to conduct at 2.0 V. Assuming each electron crossing the junction gives one photon, estimate the Planck constant in units of 10⁻³⁴ J s. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '6.613', '10⁻³⁴ J s', false, NULL, false, NULL, 'eV = hc/λ, so h = eVλ/c = 1.60 × 10⁻¹⁹ × 2.0 × 620 × 10⁻⁹ ÷ 3.00 × 10⁸ = 6.61 × 10⁻³⁴ J s. Mark scheme (3 marks). C1: eV = hc/λ. C1: rearranged for h. A1: h = 6.61 × 10⁻³⁴ J s.', 3, NULL, NULL),
('9bac4709-f8d1-57a1-814d-d2c4669aa315', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 25, 25, 'Visible light runs from 380 nm to 750 nm. Calculate the photon energy at the red end, 750 nm, in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.657', 'eV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (750 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 1.66 eV. Mark scheme (3 marks). C1: E = hc/λ. C1: in eV. A1: E = 1.66 eV.', 3, NULL, NULL),
('f1fcac66-5bcc-5c09-853c-70644aba7b24', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 26, 26, 'Which graph of photon energy E against wavelength λ is correct?', NULL, 2, 'multiple_choice'::answer_type, 'A curve with E falling as λ increases, E ∝ 1/λ', NULL, false, NULL, false, NULL, 'E = hc/λ is an inverse proportion. Mark scheme (3 marks). C1: E = hc/λ. C1: inverse relationship. A1: B (A curve with E falling as λ increases, E ∝ 1/λ).', 3, NULL, NULL),
('2ef28f2f-6615-5c87-84db-365ca6ffd3bb', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 27, 27, 'Electrons in an X-ray tube are accelerated through 30 kV. Calculate the shortest wavelength of the X-rays produced, in units of 10⁻¹¹ m. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '4.144', '10⁻¹¹ m', false, NULL, false, NULL, 'E(max) = eV = 1.60 × 10⁻¹⁹ × 30 × 10³ = 4.8 × 10⁻¹⁵ J. λ(min) = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 4.8 × 10⁻¹⁵ = 4.14 × 10⁻¹¹ m. Mark scheme (3 marks). C1: E = eV. C1: λ = hc/E. A1: λ(min) = 4.14 × 10⁻¹¹ m.', 3, NULL, NULL),
('c7eed881-5234-5f48-a3c8-5228beef0cc7', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 28, 28, 'Calculate the wavelength, in nm, of a photon with just enough energy (13.6 eV) to ionise a hydrogen atom. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '91.41 nm', 'nm', false, NULL, false, NULL, 'λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (13.6 × 1.60 × 10⁻¹⁹) = 9.141 × 10⁻⁸ m. In nm: 9.141 × 10⁻⁸ × 10⁹ = 91.4. Mark scheme (3 marks). C1: eV to J. C1: λ = hc/E. A1: λ = 91.4 nm.', 3, NULL, NULL),
('c6ecacfd-ee64-549c-8561-01efb29b8385', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 29, 29, 'Calculate (energy of a microwave photon of 10 GHz) ÷ (energy of a radio photon of 100 MHz).', NULL, 2, 'numeric'::answer_type, '100', NULL, false, NULL, false, NULL, 'E ∝ f, so ratio = 10 × 10⁹ ÷ 100 × 10⁶ = 100. Mark scheme (3 marks). C1: E = hf. C1: ratio. A1: ratio = 100.', 3, NULL, NULL),
('f4d8054c-530d-55cd-a746-7bfa034edf2d', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 30, 30, 'A green laser pointer of power 5.0 mW emits light of wavelength 520 nm. How many photons does it emit per second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.307e16', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 520 × 10⁻⁹ = 3.825 × 10⁻¹⁹ J. n = 5.0 × 10⁻³ ÷ 3.825 × 10⁻¹⁹ = 1.31 × 10¹⁶. Mark scheme (4 marks). C1: photon energy. C1: mW to W. C1: n = P/E. A1: n = 1.31 × 10¹⁶.', 4, NULL, NULL),
('be8edbf3-d7a4-582c-8903-54e5ec1f5ae3', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 31, 31, 'Cobalt-60 emits gamma photons of energy 1.25 MeV. Calculate this energy in units of 10⁻¹³ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2', '10⁻¹³ J', false, NULL, false, NULL, 'E = 1.25 × 10⁶ × 1.60 × 10⁻¹⁹ = 2.0 × 10⁻¹³ J. Mark scheme (3 marks). C1: MeV to eV. C1: eV to J. A1: E = 2.0 × 10⁻¹³ J.', 3, NULL, NULL),
('b278404f-7f7f-51f2-8bc0-ed0acbe0a442', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 32, 32, 'Why can ultraviolet light cause sunburn while far more intense infrared does not?', NULL, 2, 'multiple_choice'::answer_type, 'Each ultraviolet photon has enough energy to break chemical bonds in skin; an infrared photon does not', NULL, false, NULL, false, NULL, 'Damage depends on the energy per photon, not the total power. Mark scheme (3 marks). C1: photon energy. C1: bond-breaking threshold. A1: C (Each ultraviolet photon has enough energy to break chemical bonds in skin; an infrared photon does not).', 3, NULL, NULL),
('2c09685f-9ddb-521f-9c63-bdbae463a87a', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 33, 33, 'Breaking a particular chemical bond needs 3.6 eV. What is the longest wavelength of light, in nm, whose photons can break it? Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '345.3 nm', 'nm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (3.6 × 1.60 × 10⁻¹⁹) = 3.453 × 10⁻⁷ m. In nm: 3.453 × 10⁻⁷ × 10⁹ = 345. Mark scheme (3 marks). C1: E = hc/λ. C1: rearranged. A1: λ = 345 nm.', 3, NULL, NULL),
('3788317f-803b-5435-8f9d-5b05d8a8357a', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 34, 34, 'Calculate (energy of a 200 nm ultraviolet photon) ÷ (energy of a 1000 nm infrared photon).', NULL, 2, 'numeric'::answer_type, '5', NULL, false, NULL, false, NULL, 'E ∝ 1/λ: ratio = 1000 ÷ 200 = 5.0. Mark scheme (3 marks). C1: E ∝ 1/λ. C1: ratio. A1: ratio = 5.0.', 3, NULL, NULL),
('d9c8511c-99be-5282-aae4-dba787058a53', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 35, 35, 'Two lamps emit the same power, one at 400 nm and one at 800 nm. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The 800 nm lamp emits twice as many photons per second', NULL, false, NULL, false, NULL, 'n = P/E = Pλ/hc, so for equal power the photon rate is proportional to wavelength. Mark scheme (3 marks). C1: E ∝ 1/λ. C1: n ∝ λ for equal power. A1: A (The 800 nm lamp emits twice as many photons per second).', 3, NULL, NULL),
('37069948-01cb-55f2-9bd3-120f2cdb4bc5', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 36, 36, 'Chlorophyll absorbs red light of wavelength 680 nm. Calculate the energy carried by one mole of these photons, in kJ. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '176.1 kJ', 'kJ', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 680 × 10⁻⁹ = 2.925 × 10⁻¹⁹ J. Per mole = 6.02 × 10²³ × 2.925 × 10⁻¹⁹ = 1.761 × 10⁵ J. In kJ: 1.761 × 10⁵ ÷ 10³ = 176. Mark scheme (4 marks). C1: photon energy. C1: × N_A. C1: J to kJ. A1: E = 176 kJ.', 4, NULL, NULL),
('4d6e716a-ba6c-5215-95b5-f1e787c6182d', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 37, 37, 'Electrons accelerated through 2.5 kV strike a metal target. Calculate the highest frequency of the X-rays produced, in units of 10¹⁷ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '6.033', '10¹⁷ Hz', false, NULL, false, NULL, 'hf(max) = eV, so f = 1.60 × 10⁻¹⁹ × 2.5 × 10³ ÷ 6.63 × 10⁻³⁴ = 6.03 × 10¹⁷ Hz. Mark scheme (3 marks). C1: hf = eV. C1: substitution. A1: f = 6.03 × 10¹⁷ Hz.', 3, NULL, NULL),
('3382d5c8-a246-559f-be1a-7e4b872727cc', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 38, 38, 'Radiation is called ionising when one photon can remove an electron from an atom. Roughly which photon energies are ionising?', NULL, 2, 'multiple_choice'::answer_type, 'Above about 10 eV (far ultraviolet, X-rays and gamma rays)', NULL, false, NULL, false, NULL, 'Ionisation energies of atoms are typically 5–25 eV. Mark scheme (3 marks). C1: ionisation energy ~10 eV. C1: UV/X/gamma. A1: D (Above about 10 eV (far ultraviolet, X-rays and gamma rays)).', 3, NULL, NULL),
('3b26eff0-0b68-529c-ab30-7594bef625ca', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 39, 39, 'How many photons of 1.0 eV together carry the same energy as one photon of 1.0 keV?', NULL, 2, 'numeric'::answer_type, '1000', NULL, false, NULL, false, NULL, 'N = 1.0 × 10³ ÷ 1.0 = 1000. Mark scheme (3 marks). C1: keV to eV. C1: ratio. A1: N = 1000.', 3, NULL, NULL),
('1cd8725f-fdf0-59f7-881c-9569e62c261d', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 40, 40, 'An X-ray photon carries 1.0 × 10⁻¹⁵ J. Calculate its wavelength in units of 10⁻¹¹ m. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '19.89', '10⁻¹¹ m', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1.0 × 10⁻¹⁵ = 1.99 × 10⁻¹⁰ m. Mark scheme (3 marks). C1: λ = hc/E. C1: substitution. A1: λ = 19.9 × 10⁻¹¹ m.', 3, NULL, NULL),
('08610a84-a797-5a18-a5ae-7360783372da', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 41, 41, 'A useful shortcut gives a photon''s energy in eV as about 1240 divided by its wavelength in nm. Where does 1240 come from?', NULL, 2, 'multiple_choice'::answer_type, 'hc/e expressed in eV nm', NULL, false, NULL, false, NULL, 'hc/e = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1.60 × 10⁻¹⁹ ≈ 1.24 × 10⁻⁶ V m. Mark scheme (3 marks). C1: E = hc/λ. C1: units eV nm. A1: B (hc/e expressed in eV nm).', 3, NULL, NULL),
('1cdaa01b-880c-5e5f-964c-31f0794d615c', '7d22edfc-44c4-4846-9769-292936cb7827', 'd5ab6308-3e9f-4910-b58c-36e18c1c8758', 'a-level', '28.8', '9702 coursebook 28.8 · Photon energies', 42, 42, 'A student finds the voltage V at which LEDs of different colours start to emit: λ = 470, 525, 590, 630 nm gives V = 2.64, 2.37, 2.11, 1.97 V. (a) Explain why eV ≈ hc/λ. (b) Plot V against 1/λ and use the first and last points to find the gradient. (c) Calculate h. Give only the answer to (c), in units of 10⁻³⁴ J s. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '6.613', '10⁻³⁴ J s', false, NULL, false, NULL, '(a) Each electron crossing the junction gives up eV as one photon. (b) Gradient = (2.64 − 1.97) ÷ (1/470 × 10⁻⁹ − 1/630 × 10⁻⁹) = 0.67 ÷ 5.404 × 10⁵ = 1.240 × 10⁻⁶ V m. (c) h = e × gradient ÷ c = 1.60 × 10⁻¹⁹ × 1.240 × 10⁻⁶ ÷ 3.00 × 10⁸ = 6.61 × 10⁻³⁴ J s. Mark scheme (6 marks). B1: energy per electron = photon energy. C1: 1/λ values. C1: gradient = hc/e. M1: h = e × gradient / c. C1: value. A1: h = 6.61 × 10⁻³⁴ J s.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 316" role="img" aria-labelledby="fg2047f537-t fg2047f537-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2047f537-t">LED threshold voltages</title><desc id="fg2047f537-d">Table of LED wavelength and switch-on voltage, and a graph of V against 1/λ: the points lie on a straight line through the origin.</desc><g transform="translate(0,0)"><rect x="61.9" y="8" width="276.1" height="56" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="61.9" y="8" width="276.1" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="96.6" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill: