('cf021f68-0a17-5188-be7c-6b32a77848f8', 'cb1ee4d6-ccd5-5db9-8249-b42e3164f587', 'Light is a wave in air but particles in a vacuum', 'C', false, 2),
('3f9482bf-6c47-55b6-b809-e1633573de3a', 'cb1ee4d6-ccd5-5db9-8249-b42e3164f587', 'Light travels as a wave but exchanges energy in photons', 'D', true, 3),
('50c6611f-33ec-532e-b523-9cde629b5b1b', '4993d636-4afc-5d93-9782-54db45fe561a', 'While it travels between the slits', 'A', false, 0),
('a437e841-7d69-55f0-8c87-4220dbe21722', '4993d636-4afc-5d93-9782-54db45fe561a', 'When it is detected at the screen', 'B', true, 1),
('aa69b51b-0f4e-5eec-8132-81029c511242', '4993d636-4afc-5d93-9782-54db45fe561a', 'When it passes through the slits', 'C', false, 2),
('a7e23cba-670a-5bfc-af9e-c35e85ddad46', '4993d636-4afc-5d93-9782-54db45fe561a', 'It behaves as a particle throughout', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('357e3cae-3dd2-55a1-881b-761a41c5ce58', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 9, 9, 'An electron has a momentum of 2.0 × 10⁻²⁴ kg m s⁻¹. Calculate its de Broglie wavelength in units of 10⁻¹⁰ m. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '3.315', '10⁻¹⁰ m', false, NULL, false, NULL, 'λ = h/p = 6.63 × 10⁻³⁴ ÷ 2.0 × 10⁻²⁴ = 3.32 × 10⁻¹⁰ m. Mark scheme (2 marks). C1: λ = h/p. A1: λ = 3.32 × 10⁻¹⁰ m.', 2, NULL, NULL),
('f61e934e-3c58-5eba-9878-603e9c70eb9e', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 10, 10, 'Which equation gives the de Broglie wavelength λ of a particle of momentum p?', NULL, 1, 'multiple_choice'::answer_type, 'λ = h/p', NULL, false, NULL, false, NULL, 'de Broglie proposed λ = h/p for all particles. Mark scheme (1 mark). B1: C (λ = h/p).', 1, NULL, NULL),
('57af0a83-c0af-5e4d-873e-f771762db691', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 11, 11, 'A 0.15 kg cricket ball is bowled at 40 m s⁻¹. Calculate its de Broglie wavelength in units of 10⁻³⁴ m. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.105', '10⁻³⁴ m', false, NULL, false, NULL, 'λ = h/mv = 6.63 × 10⁻³⁴ ÷ (0.15 × 40) = 1.11 × 10⁻³⁴ m. Mark scheme (2 marks). C1: λ = h/mv. A1: λ = 1.11 × 10⁻³⁴ m.', 2, NULL, NULL),
('30136ffe-14f5-52a6-864a-96468ae70621', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 12, 12, 'Who first suggested that particles such as electrons have a wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'Louis de Broglie', NULL, false, NULL, false, NULL, 'de Broglie extended wave–particle duality from light to matter in 1924. Mark scheme (1 mark). B1: A (Louis de Broglie).', 1, NULL, NULL),
('17e175d0-5de6-5706-b279-b985318f801e', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 13, 13, 'An electron moves at 3.0 × 10⁶ m s⁻¹. Calculate its de Broglie wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '0.2426 nm', 'nm', false, NULL, false, NULL, 'λ = 6.63 × 10⁻³⁴ ÷ (9.11 × 10⁻³¹ × 3.0 × 10⁶) = 2.426 × 10⁻¹⁰ m. In nm: 2.426 × 10⁻¹⁰ × 10⁹ = 0.243. Mark scheme (2 marks). C1: λ = h/mv. A1: λ = 0.243 nm.', 2, NULL, NULL),
('13442fe0-88ba-55fa-bae8-04817a80eda7', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 14, 14, 'Which experiment first confirmed that electrons diffract?', NULL, 1, 'multiple_choice'::answer_type, 'Scattering electrons from a nickel crystal (Davisson and Germer)', NULL, false, NULL, false, NULL, 'Electrons gave diffraction maxima like X-rays. Mark scheme (1 mark). B1: D (Scattering electrons from a nickel crystal (Davisson and Germer)).', 1, NULL, NULL),
('bf7267cf-d20d-5b0c-a830-3bd4edd60198', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 15, 15, 'A particle has a de Broglie wavelength of 0.050 nm. Calculate its momentum in units of 10⁻²³ kg m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.326', '10⁻²³ kg m s⁻¹', false, NULL, false, NULL, 'p = h/λ = 6.63 × 10⁻³⁴ ÷ 0.050 × 10⁻⁹ = 1.33 × 10⁻²³ kg m s⁻¹. Mark scheme (2 marks). C1: p = h/λ. A1: p = 1.33 × 10⁻²³ kg m s⁻¹.', 2, NULL, NULL),
('d41cc360-a92c-5a44-9b10-771956657542', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 16, 16, 'The speed of an electron is doubled (well below the speed of light). What happens to its de Broglie wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'λ = h/mv, so the wavelength is inversely proportional to the speed and halves. Mark scheme (1 mark). B1: B (It halves).', 1, NULL, NULL),
('c95ae086-3996-5f42-9db1-375485520471', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 17, 17, 'Protons leave an accelerator at 1.0 × 10⁶ m s⁻¹. What is the de Broglie wavelength of each proton, in units of 10⁻¹³ m? Take h = 6.63 × 10⁻³⁴ J s and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '3.97', '10⁻¹³ m', false, NULL, false, NULL, 'λ = 6.63 × 10⁻³⁴ ÷ (1.67 × 10⁻²⁷ × 1.0 × 10⁶) = 3.97 × 10⁻¹³ m. Mark scheme (2 marks). C1: λ = h/mv. A1: λ = 3.97 × 10⁻¹³ m.', 2, NULL, NULL),
('fb053e2e-45f6-525e-920b-1d547eed80da', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 18, 18, 'An electron, a proton and an α-particle all move at the same speed. Which has the longest de Broglie wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'The electron', NULL, false, NULL, false, NULL, 'λ = h/mv: the smallest mass gives the longest λ. Mark scheme (1 mark). B1: C (The electron).', 1, NULL, NULL),
('16c1c014-67fd-52b2-99d5-06b556d36e15', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 19, 19, 'An electron has a de Broglie wavelength of 0.50 nm. Calculate its speed. Take h = 6.63 × 10⁻³⁴ J s and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '1.456e6', 'm s⁻¹', false, NULL, false, NULL, 'v = h/mλ = 6.63 × 10⁻³⁴ ÷ (9.11 × 10⁻³¹ × 0.50 × 10⁻⁹) = 1.46 × 10⁶ m s⁻¹. Mark scheme (2 marks). C1: v = h/mλ. A1: v = 1.46 × 10⁶ m s⁻¹.', 2, NULL, NULL),
('f0bd703e-dbb6-5cce-83a8-d11926a3a989', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 20, 20, 'In an electron diffraction tube, what acts as the "grating"?', NULL, 1, 'multiple_choice'::answer_type, 'The regular layers of atoms in a thin graphite film', NULL, false, NULL, false, NULL, 'Atomic spacings are similar to the electrons'' wavelength. Mark scheme (1 mark). B1: A (The regular layers of atoms in a thin graphite film).', 1, NULL, NULL),
('77915f43-983e-5d97-b0ff-d949b01cc4f2', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 21, 21, 'An electron has 1.0 × 10⁻¹⁷ J of kinetic energy. Calculate its momentum in units of 10⁻²⁴ kg m s⁻¹. Take mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '4.268', '10⁻²⁴ kg m s⁻¹', false, NULL, false, NULL, 'p = √(2mEk) = √(2 × 9.11 × 10⁻³¹ × 1.0 × 10⁻¹⁷) = 4.27 × 10⁻²⁴ kg m s⁻¹. Mark scheme (2 marks). C1: p = √(2mEk). A1: p = 4.27 × 10⁻²⁴ kg m s⁻¹.', 2, NULL, NULL),
('365b47f6-ea77-50b8-bdb7-242a0d61e8a0', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 22, 22, 'The accelerating voltage in an electron diffraction tube is increased. What happens to the electrons'' de Broglie wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases', NULL, false, NULL, false, NULL, 'Faster electrons have more momentum, so λ = h/p is smaller. Mark scheme (1 mark). B1: D (It decreases).', 1, NULL, NULL),
('54e9fc24-3d54-549b-ae48-e92ce7bc2a8e', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 23, 23, 'Electrons have a kinetic energy of 200 eV. Calculate their de Broglie wavelength in units of 10⁻¹¹ m. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8.683', '10⁻¹¹ m', false, NULL, false, NULL, 'Ek = 200 × 1.60 × 10⁻¹⁹ = 3.2 × 10⁻¹⁷ J. p = √(2 × 9.11 × 10⁻³¹ × 3.2 × 10⁻¹⁷) = 7.636 × 10⁻²⁴ kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 7.636 × 10⁻²⁴ = 8.68 × 10⁻¹¹ m. Mark scheme (2 marks). C1: p from Ek, then λ = h/p. A1: λ = 8.68 × 10⁻¹¹ m.', 2, NULL, NULL),
('79ead639-b7ab-5ca3-8eee-bc208d6688f3', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 24, 24, 'Which effect shows that electrons have wave properties?', NULL, 1, 'multiple_choice'::answer_type, 'Diffraction', NULL, false, NULL, false, NULL, 'Diffraction is a wave effect. Mark scheme (1 mark). B1: B (Diffraction).', 1, NULL, NULL),
('4c111888-253e-5fda-b673-dbcf114c2200', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 25, 25, 'A particle moving at 4.0 × 10⁵ m s⁻¹ has a de Broglie wavelength of 1.0 × 10⁻¹² m. Calculate its mass in units of 10⁻²⁷ kg. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.658', '10⁻²⁷ kg', false, NULL, false, NULL, 'm = h/λv = 6.63 × 10⁻³⁴ ÷ (1.0 × 10⁻¹² × 4.0 × 10⁵) = 1.66 × 10⁻²⁷ kg. Mark scheme (1 mark). A1: m = 1.66 × 10⁻²⁷ kg.', 1, NULL, NULL),
('a414fd8f-27bd-50b0-be30-4fb45c7d8b70', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 26, 26, 'Electrons in a diffraction tube are accelerated through 3.0 kV. Calculate their de Broglie wavelength in units of 10⁻¹¹ m. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.242', '10⁻¹¹ m', false, NULL, false, NULL, 'Ek = 1.60 × 10⁻¹⁹ × 3.0 × 10³ = 4.8 × 10⁻¹⁶ J. p = √(2 × 9.11 × 10⁻³¹ × 4.8 × 10⁻¹⁶) = 2.957 × 10⁻²³ kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 2.957 × 10⁻²³ = 2.24 × 10⁻¹¹ m. Mark scheme (3 marks). C1: Ek = eV. C1: p = √(2mEk). A1: λ = 2.24 × 10⁻¹¹ m.', 3, NULL, NULL),
('8cec29b3-4c8d-5b55-9ccb-f3e2070a086b', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 27, 27, 'In an electron diffraction tube a ring has a radius of 2.0 cm when the accelerating voltage is 2.0 kV. Taking the ring radius to be proportional to the wavelength, calculate the radius at 4.5 kV, in cm.', NULL, 2, 'numeric'::answer_type, '1.333 cm', 'cm', false, NULL, false, NULL, 'λ ∝ 1/√V, so r = 2.0 × √(2.0 ÷ 4.5) = 1.33 cm. Mark scheme (4 marks). M1: λ ∝ 1/√V. C1: r ∝ λ. C1: substitution. A1: r = 1.33 cm.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 250" role="img" aria-labelledby="fg581cd9f2-t fg581cd9f2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg581cd9f2-t">Electron diffraction tube</title><desc id="fg581cd9f2-d">An electron diffraction tube: electrons from the gun, accelerated through 2.0 kV, pass through graphite and form rings on the screen; a ring has radius 2.0 cm.</desc><rect x="20" y="94" width="70" height="32" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="55" y="140" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">electron gun</text><text x="55" y="82" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 kV</text><line x1="90" y1="100" x2="150" y2="96" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="120" x2="150" y2="124" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M150,96 A80,80 0 1,1 150,124" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="110" x2="170" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="98" x2="170" y2="122" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170" y="182" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">graphite</text><line x1="170" y1="170" x2="170" y2="126" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="74" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="146" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="110" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><line x1="300" y1="50" x2="300" y2="170" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="308" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">screen</text><circle cx="400" cy="110" r="46" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="22" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="36" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="400" y="50" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">screen, face on</text><line x1="400" y1="110" x2="436" y2="110" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="400" y="172" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">ring radius 2.0 cm</text></svg>', 'An electron diffraction tube: electrons from the gun, accelerated through 2.0 kV, pass through graphite and form rings on the screen; a ring has radius 2.0 cm.'),
('909bf003-7889-5fce-b1bd-fbef42b44f10', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 28, 28, 'For electrons accelerated from rest through a p.d. V, how does the de Broglie wavelength depend on V?', NULL, 2, 'multiple_choice'::answer_type, 'λ ∝ 1/√V', NULL, false, NULL, false, NULL, 'eV = p²/2m so p ∝ √V and λ = h/p ∝ 1/√V. Mark scheme (3 marks). C1: p = √(2meV). C1: λ ∝ 1/√V. A1: C (λ ∝ 1/√V).', 3, NULL, NULL),
('302cbb97-54d8-561d-9646-a0f050e0f56d', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 29, 29, 'A slow neutron (mass 1.67 × 10⁻²⁷ kg) has a kinetic energy of 0.025 eV. Calculate its de Broglie wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.1814 nm', 'nm', false, NULL, false, NULL, 'Ek = 0.025 × 1.60 × 10⁻¹⁹ = 4.0 × 10⁻²¹ J. p = √(2 × 1.67 × 10⁻²⁷ × 4.0 × 10⁻²¹) = 3.655 × 10⁻²⁴ kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 3.655 × 10⁻²⁴ = 1.814 × 10⁻¹⁰ m. In nm: 1.814 × 10⁻¹⁰ × 10⁹ = 0.181. Mark scheme (3 marks). C1: eV to J. C1: p = √(2mEk). A1: λ = 0.181 nm.', 3, NULL, NULL),
('34ef22e5-8047-5816-905b-66c6fa8a9e01', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 30, 30, 'Through what potential difference must electrons be accelerated from rest to have a de Broglie wavelength of 0.10 nm? Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '150.8', 'V', false, NULL, false, NULL, 'p = 6.63 × 10⁻³⁴ ÷ 0.10 × 10⁻⁹ = 6.63 × 10⁻²⁴ kg m s⁻¹. V = p²/(2me) = (6.63 × 10⁻²⁴)² ÷ (2 × 9.11 × 10⁻³¹ × 1.60 × 10⁻¹⁹) = 151 V. Mark scheme (3 marks). C1: p = h/λ. C1: eV = p²/2m. A1: V = 151 V.', 3, NULL, NULL),
('c1064758-c979-5035-8e7b-7ed6bd57efda', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 31, 31, 'An electron and a proton have the same kinetic energy. Which has the longer de Broglie wavelength?', NULL, 2, 'multiple_choice'::answer_type, 'The electron', NULL, false, NULL, false, NULL, 'p = √(2mEk) is smaller for the smaller mass, so λ = h/p is longer. Mark scheme (3 marks). C1: p = √(2mEk). C1: smaller m gives longer λ. A1: A (The electron).', 3, NULL, NULL),
('0b80518b-752e-5140-a054-d22dd11e2bce', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 32, 32, 'An electron and a proton move at the same speed. Calculate (wavelength of the electron) ÷ (wavelength of the proton). Take mₑ = 9.11 × 10⁻³¹ kg and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '1833', NULL, false, NULL, false, NULL, 'λ ∝ 1/m at equal v: ratio = 1.67 × 10⁻²⁷ ÷ 9.11 × 10⁻³¹ = 1830. Mark scheme (3 marks). C1: λ = h/mv. C1: ratio of masses. A1: ratio = 1830.', 3, NULL, NULL),
('cfe51593-724a-5a6c-b443-b92d90f0e36d', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 33, 33, 'An electron and a proton have equal kinetic energies. Calculate (wavelength of the electron) ÷ (wavelength of the proton). Take mₑ = 9.11 × 10⁻³¹ kg and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '42.82', NULL, false, NULL, false, NULL, 'λ = h/√(2mEk) ∝ 1/√m: ratio = √(1.67 × 10⁻²⁷ ÷ 9.11 × 10⁻³¹) = 42.8. Mark scheme (4 marks). C1: p = √(2mEk). M1: λ ∝ 1/√m. C1: value. A1: ratio = 42.8.', 4, NULL, NULL),
('da1b02c0-7793-546c-898b-38daacf58b1a', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 34, 34, 'Why are electron beams, rather than visible light, used to study the arrangement of atoms in crystals?', NULL, 2, 'multiple_choice'::answer_type, 'Their de Broglie wavelength can be made similar to the atomic spacing', NULL, false, NULL, false, NULL, 'Diffraction needs λ comparable to the spacing, about 10⁻¹⁰ m. Mark scheme (3 marks). C1: λ ~ atomic spacing. C1: visible λ far too long. A1: D (Their de Broglie wavelength can be made similar to the atomic spacing).', 3, NULL, NULL),
('ef815ac8-0af6-502c-aaf2-676490485780', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 35, 35, 'An electron microscope accelerates electrons through 50 kV. Ignoring relativity, calculate their de Broglie wavelength in units of 10⁻¹² m. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.492', '10⁻¹² m', false, NULL, false, NULL, 'Ek = 1.60 × 10⁻¹⁹ × 50 × 10³ = 8.0 × 10⁻¹⁵ J. p = √(2 × 9.11 × 10⁻³¹ × 8.0 × 10⁻¹⁵) = 1.207 × 10⁻²² kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 1.207 × 10⁻²² = 5.49 × 10⁻¹² m. Mark scheme (4 marks). C1: Ek = eV. C1: p = √(2mEk). C1: λ = h/p. A1: λ = 5.49 × 10⁻¹² m.', 4, NULL, NULL),
('3ae1700d-69a4-5e0f-a1f1-9f7e5e819dfe', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 36, 36, 'In an electron diffraction pattern, what do the bright rings show?', NULL, 2, 'multiple_choice'::answer_type, 'Directions in which electron waves from many atoms interfere constructively', NULL, false, NULL, false, NULL, 'Bright rings are diffraction maxima: high probability of detecting electrons. Mark scheme (3 marks). C1: constructive interference. C1: probability of arrival. A1: B (Directions in which electron waves from many atoms interfere constructively).', 3, NULL, NULL),
('6b41a042-72b8-5f81-8c7c-c215ee608366', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 37, 37, 'A neutron (mass 1.67 × 10⁻²⁷ kg) has a de Broglie wavelength of 0.20 nm. Calculate its speed. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '1985', 'm s⁻¹', false, NULL, false, NULL, 'v = h/mλ = 6.63 × 10⁻³⁴ ÷ (1.67 × 10⁻²⁷ × 0.20 × 10⁻⁹) = 1990 m s⁻¹. Mark scheme (3 marks). C1: λ = h/mv. C1: rearranged. A1: v = 1990 m s⁻¹.', 3, NULL, NULL),
('c3ab896e-f0bd-52b7-b203-5584d2c5887c', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 38, 38, 'A speck of dust of mass 1.0 × 10⁻¹⁵ kg drifts at 1.0 mm s⁻¹. Calculate its de Broglie wavelength in units of 10⁻¹⁶ m. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '6.63', '10⁻¹⁶ m', false, NULL, false, NULL, 'λ = 6.63 × 10⁻³⁴ ÷ (1.0 × 10⁻¹⁵ × 1.0 × 10⁻³) = 6.63 × 10⁻¹⁶ m. Mark scheme (3 marks). C1: mm s⁻¹ to m s⁻¹. C1: λ = h/mv. A1: λ = 6.63 × 10⁻¹⁶ m.', 3, NULL, NULL),
('dfda5c0a-de8f-5f82-8b43-06e27a582f35', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 39, 39, 'The kinetic energy of an electron is doubled (non-relativistic). By what factor does its de Broglie wavelength change?', NULL, 2, 'multiple_choice'::answer_type, '1/√2', NULL, false, NULL, false, NULL, 'p = √(2mEk) ∝ √Ek, so λ ∝ 1/√Ek. Mark scheme (3 marks). C1: p ∝ √Ek. C1: λ ∝ 1/√Ek. A1: C (1/√2).', 3, NULL, NULL),
('d532d044-281a-593e-b84a-5aaf1707e416', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 40, 40, 'Calculate the kinetic energy, in eV, of an electron whose de Broglie wavelength is 1.0 nm. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.508', 'eV', false, NULL, false, NULL, 'p = 6.63 × 10⁻³⁴ ÷ 1.0 × 10⁻⁹ = 6.63 × 10⁻²⁵ kg m s⁻¹. Ek = (6.63 × 10⁻²⁵)² ÷ (2 × 9.11 × 10⁻³¹) = 2.413 × 10⁻¹⁹ J. In eV: 2.413 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 1.51 eV. Mark scheme (3 marks). C1: p = h/λ. C1: Ek = p²/2m. A1: Ek = 1.51 eV.', 3, NULL, NULL),
('a2cf8584-a2d3-5cde-8b01-38b4b9aee859', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 41, 41, 'A single electron is fired at two narrow slits. Which describes where it is detected?', NULL, 2, 'multiple_choice'::answer_type, 'At one point, with a probability given by the electron wave''s interference pattern', NULL, false, NULL, false, NULL, 'Detection is particle-like; the probability pattern is wave-like. Mark scheme (3 marks). C1: single detection point. C1: probability from wave. A1: A (At one point, with a probability given by the electron wave''s interference pattern).', 3, NULL, NULL),
('597c9af6-7c99-54e0-9cd4-2d0159b8f1da', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 42, 42, 'Rows of atoms in a crystal are 2.1 × 10⁻¹⁰ m apart. Electrons of de Broglie wavelength 3.0 × 10⁻¹¹ m are diffracted by them. Treating the rows as a grating, calculate the first-order diffraction angle in degrees.', NULL, 2, 'numeric'::answer_type, '8.213', '°', false, NULL, false, NULL, 'sin θ = λ/d = 3.0 × 10⁻¹¹ ÷ 2.1 × 10⁻¹⁰ = 0.1429, θ = sin⁻¹ 0.1429 = 8.21°. Mark scheme (4 marks). C1: d sin θ = λ. C1: ratio. C1: angle. A1: θ = 8.21°.', 4, NULL, NULL),
('68648438-de48-5415-b7b5-36bce5ee253f', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 43, 43, 'In an electron diffraction tube, electrons are accelerated through 4.0 kV onto graphite whose atomic rows are 2.13 × 10⁻¹⁰ m apart. The screen is 0.14 m beyond the graphite. Treat the rows as a grating and the ring radius as r = L tan θ. (a) Calculate the de Broglie wavelength. (b) Calculate θ. (c) Calculate the ring radius in mm. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '12.81 mm', 'mm', false, NULL, false, NULL, '(a) p = √(2 × 9.11 × 10⁻³¹ × 1.60 × 10⁻¹⁹ × 4.0 × 10³) = 3.415 × 10⁻²³ kg m s⁻¹, λ = 6.63 × 10⁻³⁴ ÷ 3.415 × 10⁻²³ = 1.942 × 10⁻¹¹ m. (b) θ = sin⁻¹ (1.942 × 10⁻¹¹ ÷ 2.13 × 10⁻¹⁰) = 5.230°. (c) r = 0.14 × tan 5.230° = 0.01281 m. In mm: 0.01281 × 10³ = 12.8. Mark scheme (6 marks). C1: Ek = eV. C1: λ = h/p. C1: sin θ = λ/d. M1: r = L tan θ. C1: value. B1: m to mm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 250" role="img" aria-labelledby="fgb2b2f822-t fgb2b2f822-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb2b2f822-t">Electron diffraction tube</title><desc id="fgb2b2f822-d">Electrons accelerated through 4.0 kV pass through graphite; the screen is 0.14 m beyond the graphite and shows rings of radius r.</desc><rect x="20" y="94" width="70" height="32" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="55" y="140" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">electron gun</text><text x="55" y="82" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 kV</text><line x1="90" y1="100" x2="150" y2="96" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="120" x2="150" y2="124" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M150,96 A80,80 0 1,1 150,124" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="110" x2="170" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="98" x2="170" y2="122" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170" y="182" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">graphite</text><line x1="170" y1="170" x2="170" y2="126" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="74" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="146" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="110" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><line x1="300" y1="50" x2="300" y2="170" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="308" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">screen</text><polygon points="170,228 176.3,225 176.3,231" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="174.9" y1="228" x2="295.1" y2="228" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,228 293.7,231 293.7,225" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="235" y="240" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.14 m</text><circle cx="400" cy="110" r="46" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="22" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="36" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="400" y="50" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">screen, face on</text><line x1="400" y1="110" x2="436" y2="110" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="400" y="172" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">ring radius r</text></svg>', 'Electrons accelerated through 4.0 kV pass through graphite; the screen is 0.14 m beyond the graphite and shows rings of radius r.'),
('d2d80142-e2aa-523f-b125-c26b1f4f8062', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 44, 44, 'In the Davisson–Germer experiment, electrons of energy 54 eV were scattered by nickel, giving a maximum at 50° from atomic rows 2.15 × 10⁻¹⁰ m apart. (a) Calculate the de Broglie wavelength of the electrons. (b) Calculate the wavelength from d sin θ = λ. (c) Calculate the percentage difference. Give only the answer to (a), in units of 10⁻¹⁰ m. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.671', '10⁻¹⁰ m', false, NULL, false, NULL, '(a) p = √(2 × 9.11 × 10⁻³¹ × 54 × 1.60 × 10⁻¹⁹) = 3.968 × 10⁻²⁴ kg m s⁻¹, λ = 6.63 × 10⁻³⁴ ÷ 3.968 × 10⁻²⁴ = 1.67 × 10⁻¹⁰ m. (b) 2.15 × 10⁻¹⁰ × sin 50° = 1.65 × 10⁻¹⁰ m. (c) About 1.4 %. Mark scheme (6 marks). C1: Ek in J. C1: p = √(2mEk). C1: λ = h/p. C1: d sin θ. B1: close agreement. A1: λ = 1.67 × 10⁻¹⁰ m.', 6, NULL, NULL),
('90a0db02-2afc-5f76-b9c0-13931bbe3ff0', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 45, 45, 'Neutrons in equilibrium with a moderator at 300 K have a mean kinetic energy of (3/2)kT. A neutron has mass 1.67 × 10⁻²⁷ kg. (a) Calculate the mean kinetic energy. (b) Calculate the de Broglie wavelength in nm. Give only the answer to (b). Take k = 1.38 × 10⁻²³ J K⁻¹ and h = 6.63 × 10⁻³⁴ J s.', NULL, 3, 'numeric'::answer_type, '0.1456 nm', 'nm', false, NULL, false, NULL, '(a) Ek = 1.5 × 1.38 × 10⁻²³ × 300 = 6.21 × 10⁻²¹ J. (b) p = √(2 × 1.67 × 10⁻²⁷ × 6.21 × 10⁻²¹) = 4.554 × 10⁻²⁴ kg m s⁻¹, λ = 6.63 × 10⁻³⁴ ÷ 4.554 × 10⁻²⁴ = 1.456 × 10⁻¹⁰ m. In nm: 1.456 × 10⁻¹⁰ × 10⁹ = 0.146. Mark scheme (5 marks). C1: (3/2)kT. M1: p = √(2mEk). C1: λ = h/p. C1: value. A1: λ = 0.146 nm.', 5, NULL, NULL),
('124e507a-aedf-53d8-a2b1-55c8c777188e', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 46, 46, 'An electron and an X-ray photon both have a wavelength of 0.10 nm. (a) Calculate their common momentum. (b) Calculate the photon energy. (c) Calculate the electron''s kinetic energy. (d) Calculate (photon energy) ÷ (electron kinetic energy). Give only the answer to (d). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '82.44', NULL, false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 0.10 × 10⁻⁹ = 6.63 × 10⁻²⁴ kg m s⁻¹. (b) E = pc = 6.63 × 10⁻²⁴ × 3.00 × 10⁸ = 1.989 × 10⁻¹⁵ J. (c) Ek = (6.63 × 10⁻²⁴)² ÷ (2 × 9.11 × 10⁻³¹) = 2.413 × 10⁻¹⁷ J. (d) 1.989 × 10⁻¹⁵ ÷ 2.413 × 10⁻¹⁷ = 82.4. Mark scheme (6 marks). C1: p = h/λ. C1: E = pc. C1: Ek = p²/2m. M1: ratio. C1: value. A1: ratio = 82.4.', 6, NULL, NULL),
('b0752f46-0e3b-5eba-b4b7-f042e90cd392', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 47, 47, 'An electron microscope uses electrons accelerated through 100 kV. Ignoring relativity, (a) calculate their de Broglie wavelength, and (b) calculate (wavelength of 500 nm light) ÷ (electron wavelength). Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.288e5', NULL, false, NULL, false, NULL, '(a) p = √(2 × 9.11 × 10⁻³¹ × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵) = 1.707 × 10⁻²² kg m s⁻¹, λ = 6.63 × 10⁻³⁴ ÷ 1.707 × 10⁻²² = 3.883 × 10⁻¹² m. (b) 500 × 10⁻⁹ ÷ 3.883 × 10⁻¹² = 1.29 × 10⁵. Mark scheme (5 marks). C1: Ek = eV. C1: λ = h/p. M1: ratio. C1: value. A1: ratio = 1.29 × 10⁵.', 5, NULL, NULL),
('9e717747-d3ae-57ae-87c2-8d3c269ff699', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 48, 48, 'An α-particle (mass 6.64 × 10⁻²⁷ kg) has a kinetic energy of 5.0 MeV. (a) Convert the energy into joules. (b) Calculate its momentum. (c) Calculate its de Broglie wavelength. (d) Compare it with the size of a nucleus, about 10⁻¹⁴ m. Give only the answer to (c), in units of 10⁻¹⁵ m. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 3, 'numeric'::answer_type, '6.432', '10⁻¹⁵ m', false, NULL, false, NULL, '(a) Ek = 5.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 8.0 × 10⁻¹³ J. (b) p = √(2 × 6.64 × 10⁻²⁷ × 8.0 × 10⁻¹³) = 1.031 × 10⁻¹⁹ kg m s⁻¹. (c) λ = 6.63 × 10⁻³⁴ ÷ 1.031 × 10⁻¹⁹ = 6.43 × 10⁻¹⁵ m. (d) Similar in size, so α-particles probe nuclear dimensions. Mark scheme (6 marks). C1: MeV to J. C1: p = √(2mEk). M1: λ = h/p. C1: value. B1: comparison. A1: λ = 6.43 × 10⁻¹⁵ m.', 6, NULL, NULL),
('9f156866-2361-5763-8e3d-371c38caf7d2', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 49, 49, 'Electrons are to have the same wavelength as X-rays of 0.071 nm. (a) Calculate the momentum needed. (b) Calculate the accelerating potential difference required. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '299.1', 'V', false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 0.071 × 10⁻⁹ = 9.338 × 10⁻²⁴ kg m s⁻¹. (b) V = p²/(2me) = (9.338 × 10⁻²⁴)² ÷ (2 × 9.11 × 10⁻³¹ × 1.60 × 10⁻¹⁹) = 299 V. Mark scheme (5 marks). C1: p = h/λ. M1: eV = p²/2m. C1: substitution. C1: value. A1: V = 299 V.', 5, NULL, NULL),
('0aede316-5f0e-560e-8255-4f27fc37ba34', '7d22edfc-44c4-4846-9769-292936cb7827', '5859af45-f88d-5515-9a6d-031a8e33d756', 'a-level', '28.10', '9702 coursebook 28.10 · Wave–particle duality', 50, 50, 'The accelerating voltage of an electron diffraction tube is raised from 10 kV to 25 kV. (a) Show that λ ∝ 1/√V. (b) Calculate (new wavelength) ÷ (old wavelength). (c) State what happens to the rings on the screen. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.6325', NULL, false, NULL, false, NULL, '(a) eV = p²/2m gives p = √(2meV), so λ = h/√(2meV). (b) Ratio = √(10 ÷ 25) = 0.632. (c) The rings shrink to about 0.63 of their radius. Mark scheme (6 marks). B1: derivation. M1: λ ∝ 1/√V. C1: ratio. B1: rings smaller. B1: radius ∝ λ. A1: ratio = 0.632.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 250" role="img" aria-labelledby="fga2ed3727-t fga2ed3727-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga2ed3727-t">Changing the accelerating voltage</title><desc id="fga2ed3727-d">An electron diffraction tube; the accelerating voltage is raised from 10 kV to 25 kV and the rings on the screen are compared.</desc><rect x="20" y="94" width="70" height="32" rx="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="55" y="140" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">electron gun</text><text x="55" y="82" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 kV → 25 kV</text><line x1="90" y1="100" x2="150" y2="96" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="120" x2="150" y2="124" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M150,96 A80,80 0 1,1 150,124" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="110" x2="170" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="98" x2="170" y2="122" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170" y="182" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">graphite</text><line x1="170" y1="170" x2="170" y2="126" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="74" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="146" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170" y1="110" x2="300" y2="110" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><line x1="300" y1="50" x2="300" y2="170" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="308" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">screen</text><circle cx="400" cy="110" r="46" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="22" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="36" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="400" cy="110" r="3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="400" y="50" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">screen, face on</text></svg>', 'An electron diffraction tube; the accelerating voltage is raised from 10 kV to 25 kV and the rings on the screen are compared.')
