INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('7c075fca-db22-5a32-af67-746c70c67c0d', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 7, 7, 'How many photons of wavelength 450 nm are emitted each second by a 1.0 W blue lamp? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '2.262e18', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 450 × 10⁻⁹ = 4.420 × 10⁻¹⁹ J. n = 1.0 ÷ 4.420 × 10⁻¹⁹ = 2.26 × 10¹⁸. Mark scheme (2 marks). C1: n = P/E. A1: n = 2.26 × 10¹⁸.', 2, NULL, NULL),
('21bb454d-9ddd-55dc-947a-0c0c556f8db9', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 8, 8, 'In physics, what is meant by the word photon?', NULL, 1, 'multiple_choice'::answer_type, 'A quantum of electromagnetic energy', NULL, false, NULL, false, NULL, 'A photon is one packet of electromagnetic radiation, with energy hf. Mark scheme (1 mark). B1: C (A quantum of electromagnetic energy).', 1, NULL, NULL),
('dc20a174-ce1f-59c4-910b-96d5780ceb25', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 9, 9, 'Calculate the energy of a 10 GHz microwave photon in units of 10⁻²⁴ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '6.63', '10⁻²⁴ J', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 10 × 10⁹ = 6.63 × 10⁻²⁴ J. Mark scheme (2 marks). C1: E = hf. A1: E = 6.63 × 10⁻²⁴ J.', 2, NULL, NULL),
('a0e006cc-9e15-5095-8e4f-7cef91a15732', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 10, 10, 'A photon''s frequency is doubled. What happens to its energy?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'E = hf, so the photon energy is directly proportional to frequency. Mark scheme (1 mark). B1: A (It doubles).', 1, NULL, NULL),
('db32aaf9-a56a-5b9d-bcda-3aca01add264', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 11, 11, 'A photon carries 4.0 × 10⁻¹⁹ J. Calculate its wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '497.2 nm', 'nm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 4.0 × 10⁻¹⁹ = 4.972 × 10⁻⁷ m. In nm: 4.972 × 10⁻⁷ × 10⁹ = 497. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 497 nm.', 2, NULL, NULL),
('305ae8df-c751-57cc-915c-d6911b66e2a3', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 12, 12, 'Which unit could be used for the momentum of a photon?', NULL, 1, 'multiple_choice'::answer_type, 'kg m s⁻¹', NULL, false, NULL, false, NULL, 'p = h/λ has units J s ÷ m = kg m s⁻¹. Mark scheme (1 mark). B1: D (kg m s⁻¹).', 1, NULL, NULL),
('16f126ba-e7f9-5fb7-9571-ab38d2d63cc0', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 13, 13, 'Calculate the energy, in eV, of a 700 nm photon at the red end of the visible spectrum. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.776', 'eV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (700 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 1.78 eV. Mark scheme (2 marks). C1: E = hc/λ in eV. A1: E = 1.78 eV.', 2, NULL, NULL),
('7d748d05-95ea-5c6d-9fad-4794adaf88c4', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 14, 14, 'At what speed do all photons travel in a vacuum?', NULL, 1, 'multiple_choice'::answer_type, '3.00 × 10⁸ m s⁻¹, whatever their energy', NULL, false, NULL, false, NULL, 'All electromagnetic radiation travels at c in a vacuum. Mark scheme (1 mark). B1: B (3.00 × 10⁸ m s⁻¹, whatever their energy).', 1, NULL, NULL),
('9371452a-83a3-5944-8c44-49c91faf7bd5', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 15, 15, 'A beam delivers 5.0 × 10¹⁵ photons per second, each of energy 2.5 eV. Calculate the beam power in mW. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '2 mW', 'mW', false, NULL, false, NULL, 'P = 5.0 × 10¹⁵ × 2.5 × 1.60 × 10⁻¹⁹ = 0.002000 W. In mW: 0.002000 × 10³ = 2.00. Mark scheme (2 marks). C1: P = nE. A1: P = 2.0 mW.', 2, NULL, NULL),
('427de315-5b72-568a-8b6d-55bdbc6e6e4e', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 16, 16, 'For light of one wavelength, the intensity is proportional to what?', NULL, 1, 'multiple_choice'::answer_type, 'The number of photons arriving per second per unit area', NULL, false, NULL, false, NULL, 'Each photon carries hf; intensity = flux × hf. Mark scheme (1 mark). B1: C (The number of photons arriving per second per unit area).', 1, NULL, NULL),
('edab5ded-f72b-5750-b60a-e351a3a43bd8', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 17, 17, 'Calculate the energy carried by one mole of photons of wavelength 500 nm, in kJ. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and N_A = 6.02 × 10²³ mol⁻¹.', NULL, 1, 'numeric'::answer_type, '239.5 kJ', 'kJ', false, NULL, false, NULL, 'E = 6.02 × 10²³ × 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 500 × 10⁻⁹ = 2.395 × 10⁵ J. In kJ: 2.395 × 10⁵ ÷ 10³ = 239. Mark scheme (2 marks). C1: N_A × hc/λ. A1: E = 239 kJ.', 2, NULL, NULL),
('54479d32-6f0d-5e21-b132-8c42abe2bac3', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 18, 18, 'Which photons have enough energy to ionise atoms?', NULL, 1, 'multiple_choice'::answer_type, 'X-ray photons', NULL, false, NULL, false, NULL, 'Ionisation needs several eV or more per photon. Mark scheme (1 mark). B1: A (X-ray photons).', 1, NULL, NULL),
('6ef1ac65-317e-5015-9d16-6b9500ae1895', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 19, 19, 'A photon has an energy of 3.3 × 10⁻¹⁹ J. Calculate its frequency in units of 10¹⁴ Hz. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '4.977', '10¹⁴ Hz', false, NULL, false, NULL, 'f = E/h = 3.3 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 4.98 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f = E/h. A1: f = 4.98 × 10¹⁴ Hz.', 2, NULL, NULL),
('ccf3b2c9-22d3-5fad-b3de-d6404b7e2174', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 20, 20, 'How are individual photons emitted from an ordinary lamp?', NULL, 1, 'multiple_choice'::answer_type, 'At random times and in random directions', NULL, false, NULL, false, NULL, 'Spontaneous emission is random. Mark scheme (1 mark). B1: D (At random times and in random directions).', 1, NULL, NULL),
('9e571d6e-2b26-5b9c-8a91-d97034c2323a', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 21, 21, 'Light of wavelength 500 nm has an intensity of 1.0 W m⁻². How many photons cross each square metre per second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '2.514e18', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 500 × 10⁻⁹ = 3.978 × 10⁻¹⁹ J. Flux = 1.0 ÷ 3.978 × 10⁻¹⁹ = 2.51 × 10¹⁸. Mark scheme (2 marks). C1: flux = I/E. A1: flux = 2.51 × 10¹⁸.', 2, NULL, NULL),
('d86c0910-d56e-5a75-992d-379f52f1bab1', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 22, 22, 'A photon passes from air into glass. What happens to its energy?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same, because the frequency is unchanged', NULL, false, NULL, false, NULL, 'Frequency (and so hf) is set by the source; speed and wavelength change. Mark scheme (1 mark). B1: B (It stays the same, because the frequency is unchanged).', 1, NULL, NULL),
('0b8c8b9a-e933-516e-9737-b6acab328574', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 23, 23, 'How many photons of energy 1.0 × 10⁻¹⁸ J carry a total energy of 1.0 mJ?', NULL, 1, 'numeric'::answer_type, '1e15', NULL, false, NULL, false, NULL, 'N = 1.0 × 10⁻³ ÷ 1.0 × 10⁻¹⁸ = 1.0 × 10¹⁵. Mark scheme (1 mark). A1: N = 1.0 × 10¹⁵.', 1, NULL, NULL),
('632613c9-0a5d-52f2-b5a6-4225f917f91e', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 24, 24, 'A night-vision camera detects infrared of wavelength 900 nm. Calculate the photon energy in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.381', 'eV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (900 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 1.38 eV. Mark scheme (3 marks). C1: E = hc/λ. C1: in eV. A1: E = 1.38 eV.', 3, NULL, NULL),
('b0d66db7-b5c0-5339-bd28-3471dcbfd0a9', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 25, 25, 'A 2.0 W source emits light of wavelength 600 nm equally in all directions. How many photons cross each square metre per second at 5.0 m from it? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.92e16', NULL, false, NULL, false, NULL, 'n = 2.0 ÷ 3.315 × 10⁻¹⁹ = 6.033 × 10¹⁸ s⁻¹. Flux = 6.033 × 10¹⁸ ÷ (4π × 5.0²) = 1.92 × 10¹⁶. Mark scheme (3 marks). C1: photon rate. C1: ÷ 4πr². A1: flux = 1.92 × 10¹⁶.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 240" role="img" aria-labelledby="fgd5973be9-t fgd5973be9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd5973be9-t">Photons spreading out</title><desc id="fgd5973be9-d">A 2.0 W source of 600 nm light radiating equally in all directions, and a sphere of radius 5.0 m around it.</desc><path d="M269.2,235 A230,230 0 0,0 269.2,5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="82.8" y1="125.7" x2="121" y2="142.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,144.4 118.8,144.5 120.9,139.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="122.9" x2="124.6" y2="131.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,132.5 122.8,133.8 123.9,128.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="84" y1="120" x2="125.8" y2="120" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,120 124.6,122.5 124.6,117.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="117.1" x2="124.6" y2="108.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,107.5 123.9,111.1 122.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="82.8" y1="114.3" x2="121" y2="97.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,95.6 120.9,100.1 118.8,95.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><circle cx="70" cy="120" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="146" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 W</text><rect x="296" y="110" width="10" height="20" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><polygon points="70,166 76.3,163 76.3,169" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="166" x2="295.1" y2="166" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,166 293.7,169 293.7,163" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185" y="178" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 m</text></svg>', 'A 2.0 W source of 600 nm light radiating equally in all directions, and a sphere of radius 5.0 m around it.'),
('db6b730e-7ec6-54b8-8db2-445c4d42668b', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 26, 26, 'Light passes from air into water. Which statement about its photons is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Their energy stays the same but the wavelength becomes shorter', NULL, false, NULL, false, NULL, 'f is unchanged, so E = hf is unchanged; λ = v/f falls as v falls. Mark scheme (3 marks). C1: f unchanged. C1: λ = v/f decreases. A1: C (Their energy stays the same but the wavelength becomes shorter).', 3, NULL, NULL),
('28284ef1-1530-5d6e-9ab8-dc92d2d465ad', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 27, 27, 'A detector counts 20% of the photons reaching it. Light of wavelength 500 nm and power 1.0 pW reaches it. Calculate the count rate. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '5.028e5', 's⁻¹', false, NULL, false, NULL, 'n = 1.0 × 10⁻¹² ÷ 3.978 × 10⁻¹⁹ = 2.514 × 10⁶ s⁻¹. Counts = 0.20 × 2.514 × 10⁶ = 5.03 × 10⁵ s⁻¹. Mark scheme (3 marks). C1: photon rate. C1: × efficiency. A1: rate = 5.03 × 10⁵ s⁻¹.', 3, NULL, NULL),
('3e5d0856-640d-508c-86f0-143d95483c7f', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 28, 28, 'A 0.10 m² solar cell receives 800 W m⁻² of light, treated as photons of 600 nm. Each photon has a 30% chance of releasing one electron into the circuit. Calculate the current. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '11.58', 'A', false, NULL, false, NULL, 'P = 800 × 0.10 = 80 W. n = 80 ÷ 3.315 × 10⁻¹⁹ = 2.413 × 10²⁰ s⁻¹. I = 0.30 × 2.413 × 10²⁰ × 1.60 × 10⁻¹⁹ = 11.6 A. Mark scheme (4 marks). C1: P = IA. C1: photon rate. C1: I = efficiency × n × e. A1: I = 11.6 A.', 4, NULL, NULL),
('21448bfd-dd42-5f6a-92f8-a9bcd10e2e3c', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 29, 29, 'How do a gamma-ray photon and a visible photon compare?', NULL, 2, 'multiple_choice'::answer_type, 'The gamma photon has more energy and more momentum, but the same speed', NULL, false, NULL, false, NULL, 'E = hf and p = h/λ both larger for gamma; both travel at c. Mark scheme (3 marks). C1: E and p larger. C1: same speed c. A1: A (The gamma photon has more energy and more momentum, but the same speed).', 3, NULL, NULL),
('8f9cf1e7-714e-56e9-a18a-f06cad51fa99', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 30, 30, 'A photon has an energy of 2.0 eV. Calculate its momentum in units of 10⁻²⁷ kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.067', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'E = 2.0 × 1.60 × 10⁻¹⁹ = 3.2 × 10⁻¹⁹ J. p = 3.2 × 10⁻¹⁹ ÷ 3.00 × 10⁸ = 1.07 × 10⁻²⁷ kg m s⁻¹. Mark scheme (3 marks). C1: eV to J. C1: p = E/c. A1: p = 1.07 × 10⁻²⁷ kg m s⁻¹.', 3, NULL, NULL),
('f810ca54-5d04-5365-8d77-5c04a7224bce', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 31, 31, 'Light of wavelength 600 nm in air enters water of refractive index 1.33. What is the wavelength in water, in nm? (The photon energy does not change.)', NULL, 2, 'numeric'::answer_type, '451.1 nm', 'nm', false, NULL, false, NULL, 'f is unchanged and v = c/n, so λ = 600 ÷ 1.33 = 451 nm. Mark scheme (3 marks). C1: frequency unchanged. C1: λ = λ₀/n. A1: λ = 451 nm.', 3, NULL, NULL),
('bf46d872-375e-56f2-b92e-ad2a1ca39ac1', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 32, 32, 'Why does a radio receiver not detect individual photons?', NULL, 2, 'multiple_choice'::answer_type, 'Each radio photon carries so little energy that enormous numbers arrive, so the signal is effectively continuous', NULL, false, NULL, false, NULL, 'E = hf is about 10⁻²⁶ J at 100 MHz. Mark scheme (3 marks). C1: tiny hf. C1: huge photon numbers. A1: D (Each radio photon carries so little energy that enormous numbers arrive, so the signal is effectively continuous).', 3, NULL, NULL),
('e821fafd-62d4-517a-8553-90d1bf5aca9e', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 33, 33, 'How many 100 keV X-ray photons carry a total energy of 1.0 mJ? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '6.25e10', NULL, false, NULL, false, NULL, 'E = 100 × 10³ × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹⁴ J. N = 1.0 × 10⁻³ ÷ 1.6 × 10⁻¹⁴ = 6.25 × 10¹⁰. Mark scheme (3 marks). C1: keV to J. C1: N = total ÷ E. A1: N = 6.25 × 10¹⁰.', 3, NULL, NULL),
('a75e88d1-1000-504b-898f-19ffd2daf34e', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 34, 34, 'An eye can register a flash of 100 photons of 500 nm light arriving in 0.10 s. Calculate the mean power of the flash, in units of 10⁻¹⁶ W. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.978', '10⁻¹⁶ W', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 500 × 10⁻⁹ = 3.978 × 10⁻¹⁹ J. Total = 100 × 3.978 × 10⁻¹⁹ = 3.978 × 10⁻¹⁷ J. P = 3.978 × 10⁻¹⁷ ÷ 0.10 = 3.98 × 10⁻¹⁶ W. Mark scheme (4 marks). C1: photon energy. C1: total energy. C1: P = E/t. A1: P = 3.98 × 10⁻¹⁶ W.', 4, NULL, NULL),
('5dbc24cb-2558-54a4-869a-a70a522cb0d6', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 35, 35, 'What does it mean to say that the energy of electromagnetic radiation is quantised?', NULL, 2, 'multiple_choice'::answer_type, 'It can only be emitted or absorbed in whole numbers of photons, each of energy hf', NULL, false, NULL, false, NULL, 'Energy transfers come in lumps of hf. Mark scheme (3 marks). C1: discrete amounts. C1: each hf. A1: B (It can only be emitted or absorbed in whole numbers of photons, each of energy hf).', 3, NULL, NULL),
('79e2a78d-728d-518d-824d-0d9342497294', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 36, 36, 'A photon has a momentum of 1.5 × 10⁻²⁷ kg m s⁻¹. Calculate its energy in eV. Take c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.813', 'eV', false, NULL, false, NULL, 'E = pc = 1.5 × 10⁻²⁷ × 3.00 × 10⁸ = 4.5 × 10⁻¹⁹ J. In eV: 4.5 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 2.81 eV. Mark scheme (3 marks). C1: E = pc. C1: J to eV. A1: E = 2.81 eV.', 3, NULL, NULL),
('f94bd29e-7ecd-5427-9c64-95dfbbd02033', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 37, 37, 'A continuous laser emits 2.0 W of infrared light of wavelength 1064 nm. How many photons does it emit per second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.07e19', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1064 × 10⁻⁹ = 1.869 × 10⁻¹⁹ J. n = 2.0 ÷ 1.869 × 10⁻¹⁹ = 1.07 × 10¹⁹. Mark scheme (3 marks). C1: photon energy. C1: n = P/E. A1: n = 1.07 × 10¹⁹.', 3, NULL, NULL),
('a1904abb-e9ac-57fe-b508-a4f5183e43c3', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 38, 38, 'Two beams have the same intensity. Beam X is ultraviolet and beam Y is infrared. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Beam Y has the greater photon flux', NULL, false, NULL, false, NULL, 'Flux = I/hf, so the lower-energy photons must be more numerous. Mark scheme (3 marks). C1: flux = I/E. C1: infrared photons smaller E. A1: C (Beam Y has the greater photon flux).', 3, NULL, NULL),
('27a51d1a-5979-50a1-aacb-d5646be195ba', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 39, 39, 'Calculate the frequency of a photon of energy 1.0 keV, in units of 10¹⁷ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '2.413', '10¹⁷ Hz', false, NULL, false, NULL, 'E = 1.0 × 10³ × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹⁶ J. f = 1.6 × 10⁻¹⁶ ÷ 6.63 × 10⁻³⁴ = 2.41 × 10¹⁷ Hz. Mark scheme (3 marks). C1: keV to J. C1: f = E/h. A1: f = 2.41 × 10¹⁷ Hz.', 3, NULL, NULL),
('4973dd4b-e40a-5b6c-9124-4b163712aa2d', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 40, 40, 'Which statement about the photons in a beam of monochromatic light is correct?', NULL, 2, 'multiple_choice'::answer_type, 'They all have the same energy, and their number per second sets the intensity', NULL, false, NULL, false, NULL, 'One frequency means one photon energy hf. Mark scheme (4 marks). C1: single photon energy. C1: intensity from number. C1: spreading reduces flux, not hf. A1: A (They all have the same energy, and their number per second sets the intensity).', 4, NULL, NULL),
('468dc91f-fe68-5979-a070-2f6c3f9c03ae', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 41, 41, 'A 40 W filament lamp turns 10% of its power into visible light, treated as photons of 550 nm. How many visible photons does it emit per second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.106e19', NULL, false, NULL, false, NULL, 'Visible power = 0.10 × 40 = 4.0 W. n = 4.0 ÷ 3.616 × 10⁻¹⁹ = 1.11 × 10¹⁹. Mark scheme (3 marks). C1: useful power. C1: n = P/E. A1: n = 1.11 × 10¹⁹.', 3, NULL, NULL),
('bfbda518-9a0f-5444-9bac-2ca99be9f599', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 42, 42, 'A GPS satellite signal of frequency 1.575 GHz reaches a receiver with a power of 1.0 × 10⁻¹⁶ W. (a) Calculate the photon energy. (b) Calculate the number of photons arriving per second. (c) Explain why the signal behaves like a classical wave. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s.', NULL, 3, 'numeric'::answer_type, '9.576e7', NULL, false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 1.575 × 10⁹ = 1.044 × 10⁻²⁴ J. (b) n = 1.0 × 10⁻¹⁶ ÷ 1.044 × 10⁻²⁴ = 9.58 × 10⁷. (c) Around 10⁸ photons per second each with tiny energy behave as a continuous wave. Mark scheme (5 marks). C1: E = hf. M1: n = P/E. C1: value. B1: many tiny quanta. A1: n = 9.58 × 10⁷.', 5, NULL, NULL),
('4bf0af24-e5e8-5585-bc40-af5089983f7c', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 43, 43, 'A red LED starts to emit at 2.0 V. Each electron crossing the junction gives one photon. It carries 20 mA. (a) Calculate the number of electrons per second. (b) Calculate the photon energy in J. (c) Calculate the wavelength in nm. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C, h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '621.6 nm', 'nm', false, NULL, false, NULL, '(a) n = 20 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = 1.25 × 10¹⁷ s⁻¹. (b) E = eV = 1.60 × 10⁻¹⁹ × 2.0 = 3.2 × 10⁻¹⁹ J. (c) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 3.2 × 10⁻¹⁹ = 6.216 × 10⁻⁷ m. In nm: 6.216 × 10⁻⁷ × 10⁹ = 622. Mark scheme (6 marks). C1: n = I/e. C1: E = eV. M1: λ = hc/E. C1: conversion. C1: value. A1: λ = 622 nm.', 6, NULL, NULL),
('b0041244-9727-53ae-813c-ee37c6bf6577', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 44, 44, 'A pulsed laser emits pulses of 50 mJ at 1064 nm, each lasting 5.0 ns. (a) Calculate the peak power. (b) Calculate the number of photons per pulse. (c) Calculate the total momentum of the photons in one pulse. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '2.675e17', NULL, false, NULL, false, NULL, '(a) P = 50 × 10⁻³ ÷ 5.0 × 10⁻⁹ = 1.0 × 10⁷ W. (b) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1064 × 10⁻⁹ = 1.869 × 10⁻¹⁹ J; N = 50 × 10⁻³ ÷ 1.869 × 10⁻¹⁹ = 2.67 × 10¹⁷. (c) p = E/c = 50 × 10⁻³ ÷ 3.00 × 10⁸ = 1.67 × 10⁻¹⁰ kg m s⁻¹. Mark scheme (5 marks). C1: peak power. C1: photon energy. M1: N = E/hf. C1: value. A1: N = 2.67 × 10¹⁷.', 5, NULL, NULL),
('a916b781-e46a-58bc-b617-664215fbafdf', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 45, 45, 'A fluorescent dye absorbs ultraviolet photons of 365 nm and re-emits visible photons of 520 nm. (a) Calculate both photon energies in eV. (b) Calculate the energy lost per photon, in eV. (c) Calculate this loss as a percentage of the absorbed energy. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.015', 'eV', false, NULL, false, NULL, '(a) 3.406 eV and 2.391 eV. (b) 3.406 − 2.391 = 1.02 eV. (c) 29.8 %. Mark scheme (6 marks). C1: UV photon energy. C1: visible photon energy. M1: difference. C1: value. C1: percentage. A1: ΔE = 1.02 eV.', 6, NULL, NULL),
('87c65389-a470-526f-b156-a260db7cc658', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 46, 46, 'A telescope collects light from a galaxy with a mirror of area 0.50 m². The intensity at the Earth is 2.0 × 10⁻¹⁴ W m⁻² and the mean wavelength is 600 nm. (a) Calculate the power collected. (b) Calculate the number of photons collected per second. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '30166', NULL, false, NULL, false, NULL, '(a) P = 2.0 × 10⁻¹⁴ × 0.50 = 1.0 × 10⁻¹⁴ W. (b) n = 1.0 × 10⁻¹⁴ ÷ 3.315 × 10⁻¹⁹ = 3.02 × 10⁴. Mark scheme (5 marks). C1: P = IA. C1: photon energy. M1: n = P/E. C1: value. A1: n = 3.02 × 10⁴.', 5, NULL, NULL),
('3ea897d6-3eab-5c67-9826-83f3dd420588', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 47, 47, 'A 2.0 mW laser of wavelength 650 nm shines on a photodiode for 1.0 minute. (a) Calculate the energy delivered. (b) Calculate the number of photons. (c) If 70% of the photons each free one electron, calculate the charge that flows. Give only the answer to (c), in mC. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '43.92 mC', 'mC', false, NULL, false, NULL, '(a) E = 2.0 × 10⁻³ × 60 = 0.12 J. (b) N = 0.12 ÷ 3.060 × 10⁻¹⁹ = 3.922 × 10¹⁷. (c) Q = 0.70 × 3.922 × 10¹⁷ × 1.60 × 10⁻¹⁹ = 0.04392 C. In mC: 0.04392 × 10³ = 43.9. Mark scheme (6 marks). C1: E = Pt. C1: photon energy. C1: N. M1: Q = 0.70 N e. C1: value. A1: Q = 43.9 mC.', 6, NULL, NULL),
('02b9c7fe-3a1d-5f64-a7e4-85c3f519d593', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 48, 48, 'An X-ray beam of 30 keV photons delivers 2.0 × 10⁻³ J to a patient. (a) Convert the photon energy into joules. (b) Calculate the number of photons absorbed. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '4.167e11', NULL, false, NULL, false, NULL, '(a) E = 30 × 10³ × 1.60 × 10⁻¹⁹ = 4.8 × 10⁻¹⁵ J. (b) N = 2.0 × 10⁻³ ÷ 4.8 × 10⁻¹⁵ = 4.17 × 10¹¹. Mark scheme (5 marks). C1: keV to J. M1: N = total ÷ photon energy. C1: value. B1: each photon ionises. A1: N = 4.17 × 10¹¹.', 5, NULL, NULL),
('15fe35cb-0302-5841-8bd9-843de82b49ec', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 49, 49, 'Sunlight reaches the top of the atmosphere with an intensity of 1.36 kW m⁻². Model it as photons of 550 nm. (a) Calculate the photon flux. (b) Calculate the radiation pressure on a perfectly absorbing surface. (c) Calculate the momentum delivered to 1.0 m² each second by the photons. Give only the answer to (a). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '3.761e21', NULL, false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 550 × 10⁻⁹ = 3.616 × 10⁻¹⁹ J; flux = 1.36 × 10³ ÷ 3.616 × 10⁻¹⁹ = 3.76 × 10²¹ m⁻² s⁻¹. (b) p = I/c = 1360 ÷ 3.00 × 10⁸ = 4.53 × 10⁻⁶ Pa. (c) 4.53 × 10⁻⁶ kg m s⁻¹ each second. Mark scheme (6 marks). C1: photon energy. M1: flux = I/E. C1: value. C1: pressure I/c. B1: momentum per second = force. A1: flux = 3.76 × 10²¹.', 6, NULL, NULL),
('7b043ecd-eef7-5d5e-8485-b8335747a427', '7d22edfc-44c4-4846-9769-292936cb7827', '06ec1944-95d0-4562-b279-41821556ab5c', 'a-level', '28.11', '9702 coursebook 28.11 · Revisiting photons', 50, 50, 'A detector of area 1.0 cm² is 3.0 m from a 5.0 W source of 590 nm light that radiates equally in all directions. (a) Calculate the intensity at the detector. (b) Calculate the number of photons hitting the detector per second. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '1.311e13', NULL, false, NULL, false, NULL, '(a) I = 5.0 ÷ (4π × 3.0²) = 0.04421 W m⁻². (b) P = 0.04421 × 1.0 × 10⁻⁴ = 4.421 × 10⁻⁶ W; n = 4.421 × 10⁻⁶ ÷ 3.371 × 10⁻¹⁹ = 1.31 × 10¹³. Mark scheme (5 marks). C1: inverse-square intensity. C1: cm² to m². M1: n = P/E. C1: value. A1: n = 1.31 × 10¹³.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 240" role="img" aria-labelledby="fgaaae180d-t fgaaae180d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaaae180d-t">Detector near a lamp</title><desc id="fgaaae180d-d">A detector of area 1.0 cm² placed 3.0 m from a 5.0 W source of 590 nm light that radiates equally in all directions.</desc><path d="M269.2,235 A230,230 0 0,0 269.2,5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="82.8" y1="125.7" x2="121" y2="142.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,144.4 118.8,144.5 120.9,139.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="122.9" x2="124.6" y2="131.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,132.5 122.8,133.8 123.9,128.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="84" y1="120" x2="125.8" y2="120" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,120 124.6,122.5 124.6,117.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="83.7" y1="117.1" x2="124.6" y2="108.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128.7,107.5 123.9,111.1 122.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="82.8" y1="114.3" x2="121" y2="97.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="124.8,95.6 120.9,100.1 118.8,95.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><circle cx="70" cy="120" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="70" y="146" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 W</text><rect x="296" y="110" width="10" height="20" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="290" y="98" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0 cm²</text><polygon points="70,166 76.3,163 76.3,169" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="74.9" y1="166" x2="295.1" y2="166" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,166 293.7,169 293.7,163" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185" y="178" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 m</text></svg>', 'A detector of area 1.0 cm² placed 3.0 m from a 5.0 W source of 590 nm light that radiates equally in all directions.')
