('e362bc86-4b7c-5ad7-bd63-87e822c462f3', '7d748d05-95ea-5c6d-9fad-4794adaf88c4', 'Faster for higher energies', 'A', false, 0),
('e489ddf5-9a20-5880-9253-a8db4ab9ef77', '7d748d05-95ea-5c6d-9fad-4794adaf88c4', '3.00 × 10⁸ m s⁻¹, whatever their energy', 'B', true, 1),
('bc92b7fb-0a65-592a-97b1-6699cd1f5323', '7d748d05-95ea-5c6d-9fad-4794adaf88c4', 'Slower for higher energies', 'C', false, 2),
('475b9f32-8529-5e85-a3fa-6fb38a7e37c5', '7d748d05-95ea-5c6d-9fad-4794adaf88c4', 'At a speed that depends on the source', 'D', false, 3),
('514dd3a9-7a53-5a95-88aa-ec2b2523250c', '427de315-5b72-568a-8b6d-55bdbc6e6e4e', 'The energy of each photon', 'A', false, 0),
('521372ca-9255-563a-ad62-65db4d094b6f', '427de315-5b72-568a-8b6d-55bdbc6e6e4e', 'The speed of the photons', 'B', false, 1),
('fe792e38-d17e-5c73-851b-5eb8dd37cb0d', '427de315-5b72-568a-8b6d-55bdbc6e6e4e', 'The number of photons arriving per second per unit area', 'C', true, 2),
('c03ceedc-383e-542d-8add-c96f4f45983e', '427de315-5b72-568a-8b6d-55bdbc6e6e4e', 'The wavelength', 'D', false, 3),
